def group_absent(pid):
    try:os.killpg(pid,0);return False
    except ProcessLookupError:return True
    except OSError:return None

def owned_group(ownership):
    if ownership['absent']:
        return True
    absent=group_absent(ownership['pgid'])
    if absent is True:
        ownership['absent']=True
    return absent

def send_owned(ownership,sig):
    if owned_group(ownership) is True:
        return {'attempted':False,'outcome':'not-attempted'}
    try:
        os.killpg(ownership['pgid'],sig)
        return {'attempted':True,'outcome':'sent-success'}
    except ProcessLookupError:
        ownership['absent']=True
        return {'attempted':True,'outcome':'ESRCH-absent'}
    except PermissionError:
        return {'attempted':True,'outcome':'EPERM-unknown'}
    except OSError:
        return {'attempted':True,'outcome':'other-unknown'}

